    bump.quad(cladDk,
      V(-recessW, recessY0, recessZ), V(-recessW, recessY0, bZUpper),
      V(recessW, recessY0, bZUpper), V(recessW, recessY0, recessZ),
      { out: [0, -1, 0] });
    bump.quad(cladDk,
      V(-recessW, recessY1, bZUpper), V(-recessW, recessY1, recessZ),
      V(recessW, recessY1, recessZ), V(recessW, recessY1, bZUpper),
      { out: [0, 1, 0] });
    bump.quad(cladDk,
      V(-recessW, recessY0, recessZ), V(-recessW, recessY1, recessZ),
      V(-recessW, recessY1, bZUpper), V(-recessW, recessY0, bZUpper),
      { out: [-1, 0, 0] });
    bump.quad(cladDk,
      V(recessW, recessY0, bZUpper), V(recessW, recessY1, bZUpper),
      V(recessW, recessY1, recessZ), V(recessW, recessY0, recessZ),
      { out: [1, 0, 0] });
    /* Lower rear face — shallower, full width between the wraps. */
    bump.quad(cladLt,
      V(-bW + chamfer, bY0, bZLower), V(bW - chamfer, bY0, bZLower),
      V(bW - chamfer, bYStep, bZLower), V(-bW + chamfer, bYStep, bZLower),
      { out: [0, 0, -1] });
    /* Step top, between upper and lower faces. */
    bump.quad(clad,
      V(-bW + chamfer, bYStep, bZLower), V(bW - chamfer, bYStep, bZLower),
      V(bW - chamfer, bYStep, bZUpper), V(-bW + chamfer, bYStep, bZUpper),
      { out: [0, 1, 0] });
    /* Thin lower light strip, pale silver, just above the bottom lip. */
    const stripMat = new T.MeshBasicMaterial({ color: 0xc8cdd6, toneMapped: false });
    const stripH = m(0.018), stripY = bY0 + m(0.035);
    const strip = box((bW - chamfer) * 2 + m(0.04), stripH, m(0.02), stripMat, 0, stripY, bZLower - m(0.012));
