    bump.quad(cladDk,
      V(-bW + chamfer, bY0, bZLower), V(-bW + chamfer, bY0, bZ0 + m(0.02)),
      V(bW - chamfer, bY0, bZ0 + m(0.02)), V(bW - chamfer, bY0, bZLower),
      { out: [0, -1, 0] });
    add("bumper-r", bump.build());


    /* Yellow THERAPY TOASTER plate, centered in the bumper recess. Never the real number. */
    const plateMat = new T.MeshBasicMaterial({
      map: (mats.frontPlate && mats.frontPlate.map) || (G.makeFrontPlateTexture && G.makeFrontPlateTexture()) || null,
      color: 0xffffff, toneMapped: false,
    });
