      const side = i % 2 ? 1 : -1;
      const dist = 95 + (i % 11) * 16 + rndS() * 10;
      const a = along(pct, side, dist);
      pushStone(a.x + (rndS() - 0.5) * 18, a.z + (rndS() - 0.5) * 18, 1.3 + (i % 6) * 0.2, null, 0, i % 4);
