    hills.forEach(function (h, hi) {
      if (hi >= nearN) return;
      for (let k = 0; k < 14; k++) {
        const ang = rndS() * Math.PI * 2;
        const rr = h.R * (0.2 + rndS() * 0.5);
        const x = h.x + Math.cos(ang) * rr;
        const z = h.z + Math.sin(ang) * rr;
        const horiz = Math.hypot(x - h.x, z - h.z);
        const surface = h.y + h.sy * Math.sqrt(Math.max(0, h.R * h.R - horiz * horiz));
        rockA.push({ x: x, y: Math.max(0, surface), z: z, ry: ang, sx: 1.2 + rndS(), sy: 0.7, sz: 1.1 + rndS() });
      }
    });
    const grassMeshA = addInstanced(root, grassBodyGeo(), grassMat, grassA, null, 0);
    if (grassMeshA) grassMeshA.userData.keepForPhoto = true;
    addInstanced(root, rockBodyGeo(0), rockMat, rockA, null, 0);
    const grassMeshB = addInstanced(dense, grassBodyGeo(), grassMat, grassB, null, 0);
    if (grassMeshB) grassMeshB.userData.keepForPhoto = true;
    addInstanced(dense, rockBodyGeo(1), rockMat, rockB, null, 0);

    /* ---- bare twisty trees ---- */
    const bark = toon(0x8a5a6e);
    const treeBuckets = [[], [], []];
    for (let i = 0; i < 80; i++) {
      const pct = (i + 0.4) / 64;
      const side = i % 2 ? -1 : 1;
      const a = along(pct, side, 110 + (i % 7) * 16);
      if (!offRoad(a.x, a.z, 16)) continue;
      treeBuckets[i % 3].push({
        x: a.x, y: 0, z: a.z,
        ry: rndS() * Math.PI * 2,
        sx: 1.15 + (i % 4) * 0.18, sy: 1.15 + (i % 5) * 0.15, sz: 1.15 + (i % 4) * 0.18,
      });
    }
    for (let t = 0; t < 3; t++) {
      addInstanced(root, treeBodyGeo(t), bark, treeBuckets[t], inkGroup, 0.1);
    }

    /* ---- friendly toast lanterns along the edges ---- */
    G._gyLanternLights = [];
    const lanN = 12;
    for (let i = 0; i < lanN; i++) {
      const pct = (i + 0.5) / lanN;
      const side = i % 2 ? 1 : -1;
      const a = along(pct, side, 62);
      if (!offRoad(a.x, a.z, 6)) continue;
      const lan = G.buildToastLantern(mats, i);
      lan.position.set(a.x, 0, a.z);
      lan.rotation.y = a.face;
      lan.scale.setScalar(2.3);
      root.add(lan);
      if (lan.userData.lanternLight) G._gyLanternLights.push(lan.userData.lanternLight);
    }
    if (cryptP) {
      [-1, 1].forEach(function (s, i) {
        const lan = G.buildToastLantern(mats, 80 + i);
        lan.position.set(cryptP.x + s * 28, 1.2, cryptP.y + 18);
        lan.scale.setScalar(2.6);
        root.add(lan);
        if (lan.userData.lanternLight) G._gyLanternLights.push(lan.userData.lanternLight);
      });
    }

    /* ---- wispy ground fog ---- */
    const fogMat = new (THREE().MeshToonMaterial)({
      color: 0xf0d0e0, gradientMap: G._toonGrad || null,
      transparent: true, opacity: 0.32, depthWrite: false, fog: false,
    });
    for (let i = 0; i < 40; i++) {
      const pct = (i + 0.2) / 40;
      const side = i % 2 ? 1 : -1;
      const a = along(pct, side, 70 + (i % 6) * 18);
      const puff = new (THREE().Mesh)(new (THREE().SphereGeometry)(16, 8, 6), fogMat);
      puff.scale.set(1.8 + (i % 3) * 0.6, 0.22 + (i % 4) * 0.05, 1.2 + (i % 3) * 0.4);
      puff.position.set(a.x, 1.6, a.z);
      puff.renderOrder = 2;
      fogGroup.add(puff);
    }

    /* stylized clouds live on the shared comic sky (G._comicClouds) */
    /* extra sparkly stars in the graveyard sky */
    const n = 180;
    const sp = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2, b = 0.25 + Math.random() * 1.0;
      const r = 650;
      sp[i * 3] = Math.cos(a) * Math.cos(b) * r;
      sp[i * 3 + 1] = Math.sin(b) * r;
      sp[i * 3 + 2] = Math.sin(a) * Math.cos(b) * r;
    }
    const sg = new (THREE().BufferGeometry)();
    sg.setAttribute("position", new (THREE().BufferAttribute)(sp, 3));
    const stars = new (THREE().Points)(sg, new (THREE().PointsMaterial)({
      color: 0xfff4c8, size: 2.4, sizeAttenuation: false, fog: false, transparent: true, opacity: 0.95,
    }));
    if (G._skyRoot) G._skyRoot.add(stars);
    else root.add(stars);
