      "therapy": { text: "THERAPY TOASTER", colors: ["#ffd400", "#ff5a2a", "#3ad0ff", "#ff4fa3"], crown: true },
      "cyber": { text: "CYBER", colors: ["#3ad0ff", "#ff3b5c", "#c8ff4a", "#ff9a1a"], crown: false },
      "skullz": { text: "SKULLZ", colors: ["#ff4fa3", "#b14cff", "#ffe14a", "#ff5a2a"], crown: true },
      "going": { text: "WE'RE GOING CYBER", colors: ["#111111", "#ff2a4a", "#2ad0ff", "#ffd400"], crown: false },
