      const heading = Math.atan2(k.vy || 0, k.vx || 0);
      const clean = Math.abs(G.angWrap(heading - k.ang)) < 0.65 && k.spinT <= 0 && impact > 5 && impact < 80;
      if (clean && !wasShortcut) {
        k.boostT = Math.max(k.boostT, 0.20 + Math.min(0.14, impact * 0.003));
        if (!k.boostKind || k.boostKind === "land") k.boostKind = "land";
        k._cleanLand = 0.35;
        if (k._airTrick) {
          k.boostT = Math.max(k.boostT, 0.38);
          k._airTrick = false;
        }
      }
