    frameRear() { if (G.frameRear) G.frameRear(); },
    frameStyle2Compare() { if (G.frameStyle2Compare) G.frameStyle2Compare(); },
    frameRearCompare() { if (G.frameRearCompare) G.frameRearCompare(); },
    frameGraffiti() { if (G.frameGraffiti) G.frameGraffiti(); },
    frameGraveyardWide() { if (G.frameGraveyardWide) G.frameGraveyardWide(); },
