      if (!d || !G.freezeCam) return;
      const p = G.field && G.field.player;
      if (p && sc) {
        p.x = 618; p.y = 1148; p.alt = 0; p.vz = 0;
        p.ang = Math.PI / 2; p.speed = 0; p.vx = 0; p.vy = 0;
        if (G.poseKart && G.kartMeshes) {
          const m = G.kartMeshes.get(p.id);
          if (m) G.poseKart(m, p);
        }
      }
