      const y1 = y0 + height * 0.9;
      for (let i = 0; i < cols.length; i++) {
        const c = cols[i];
        if (c.off) continue;
        if (y1 < c.miny + 0.05 || y0 > c.maxy - 0.05) continue;
        if (x + radius > c.minx && x - radius < c.maxx && z + radius > c.minz && z - radius < c.maxz) return c;
      }
