      sand: new T.MeshStandardMaterial({ map: sandTex, color: sandTex ? 0xffffff : 0xc8b890, roughness: 0.96, metalness: 0, envMapIntensity: 0.06 }),
      concrete: new T.MeshStandardMaterial({ map: concTex, color: concTex ? 0xffffff : 0x9a958c, roughness: 0.92, metalness: 0, envMapIntensity: 0.08 }),
      wood: new T.MeshStandardMaterial({ color: 0x6a4e32, roughness: 0.9, metalness: 0 }),
