    if (!Array.isArray(s.fridge)) s.fridge = [];
    if (s.job === undefined) s.job = null;
    if (s.day == null) s.day = 1;
    if (!s.tod) s.tod = "day";
    s.passedOut = false;
    s.passOutT = 0;
    s.payFlashT = s.payFlashT || 0;
    s.working = false;
    s.lifeReady = true;
