      fridge: (s.fridge || []).map(function (it) { return { id: it.id }; }),
      job: s.job ? {
        type: s.job.type, title: s.job.title, pay: s.job.pay, bonus: s.job.bonus,
        timeLeft: s.job.timeLeft, timeLimit: s.job.timeLimit, late: !!s.job.late,
        need: s.job.need, have: s.job.have, holding: !!s.job.holding,
        dest: s.job.dest, destName: s.job.destName
      } : null,
