    if (!s || !data) return;
    s.cash = (typeof data.cash === "number") ? data.cash : START_CASH;
    s.hunger = (typeof data.hunger === "number") ? data.hunger : START_HUNGER;
    s.bag = inflateList(data.bag);
    s.fridge = inflateList(data.fridge);
    s.job = null;
    s.day = (typeof data.day === "number") ? data.day : 1;
