    root.add(box(3.6, 0.16, 1.7, porchM, west.x, 0.16, west.z + 0.05));
    root.add(box(3.8, 0.08, 1.9, roofM, west.x, 2.55, west.z + 0.15));
    root.add(box(0.12, 2.3, 0.12, railM, west.x - 1.55, 1.25, west.z + 0.8));
    root.add(box(0.12, 2.3, 0.12, railM, west.x + 1.55, 1.25, west.z + 0.8));
    root.add(box(3.15, 0.06, 0.06, railM, west.x, 1.05, west.z + 0.8));
    root.add(box(3.15, 0.06, 0.06, railM, west.x, 0.7, west.z + 0.8));
