    const beachGrid = decodeGrid(map.beachGrid);
    G.summerWorld.landGrid = landGrid;
    G.summerWorld.beachGrid = beachGrid;
    G.summerWorld.map = map;
    G.summerWorld.bbox = map.bbox;
    G.summerWorld.landmarks = map.landmarks || {};

    /* ---- Water plane under everything ---- */
    const bb = map.bbox;
    const wW = (bb[2] - bb[0]) + 200, wD = (bb[3] - bb[1]) + 200;
    const waterMat = G.makeOceanMaterial ? G.makeOceanMaterial("ocean") : new T.MeshStandardMaterial({ color: 0x3a6a88, roughness: 0.28, metalness: 0.1 });
    if (waterMat.fog !== undefined) waterMat.fog = false;
    const water = new T.Mesh(new T.PlaneGeometry(wW, wD, 48, 48), waterMat);
    water.rotation.x = -Math.PI / 2;
    /* Keep the water below the land so it cannot paint over the island
       (the ocean shader is transparent and does not write depth). */
    waterMat.depthWrite = true;
    if (waterMat.uniforms && waterMat.uniforms.waveHole) waterMat.uniforms.waveHole.value = 155;
    water.position.set((bb[0] + bb[2]) / 2, -0.85, (bb[1] + bb[3]) / 2);
    water.userData.ocean = true;
    group.add(water);
    /* Distance-to-shore map so shallows and breaking waves follow the real coastline. */
    if (landGrid && waterMat.uniforms) {
      function onShore(x, z) {
        return gridAt(landGrid, x, z) || (beachGrid && gridAt(beachGrid, x, z));
      }
      const SW = 256, SH = 256;
      const ox = bb[0] - 80, oz = bb[1] - 80;
      const sx = (bb[2] - bb[0]) + 160, sz = (bb[3] - bb[1]) + 160;
      const data = new Uint8Array(SW * SH * 4);
      for (let j = 0; j < SH; j++) {
        for (let i = 0; i < SW; i++) {
          const x = ox + (i + 0.5) / SW * sx;
          const z = oz + (j + 0.5) / SH * sz;
          const k = (j * SW + i) * 4;
          if (onShore(x, z)) { data[k] = data[k+1] = data[k+2] = 0; data[k+3] = 255; continue; }
          let d = 64;
          for (let r = 2; r <= 64; r += 2) {
            if (onShore(x + r, z) || onShore(x - r, z) ||
                onShore(x, z + r) || onShore(x, z - r) ||
                onShore(x + r, z + r) || onShore(x - r, z - r) ||
                onShore(x + r, z - r) || onShore(x - r, z + r)) { d = r; break; }
          }
          const v = Math.round((d / 64) * 255);
          data[k] = data[k+1] = data[k+2] = v; data[k+3] = 255;
        }
      }
      const tex = new T.DataTexture(data, SW, SH, T.RGBAFormat);
      tex.needsUpdate = true;
      tex.flipY = false;
      tex.minFilter = T.LinearFilter;
      tex.magFilter = T.LinearFilter;
      tex.wrapS = tex.wrapT = T.ClampToEdgeWrapping;
      if (tex.colorSpace != null && T.NoColorSpace) tex.colorSpace = T.NoColorSpace;
      waterMat.uniforms.shoreMap.value = tex;
      waterMat.uniforms.hasShore.value = 1;
      waterMat.uniforms.shoreOrigin.value.set(ox, oz);
      waterMat.uniforms.shoreSize.value.set(sx, sz);
      G.summerWorld.shore = { tex: tex, ox: ox, oz: oz, sx: sx, sz: sz };
      if (G.applyShoreToWater) G.applyShoreToWater();
    }
    if (G.attachOceanSwell) G.attachOceanSwell(group, -0.85);

    /* ---- Height + collider samples for roads / bridge ---- */
    const segs = [];
    function addSegs(pts, hw, isBridge) {
      for (let i = 0; i < pts.length - 1; i++) {
        const a = pts[i], b = pts[i + 1];
        const ax = a[0], az = a.length > 2 ? a[2] : a[1];
        const bx = b[0], bz = b.length > 2 ? b[2] : b[1];
        const ay = a.length > 2 ? a[1] : 0.03;
        const by = b.length > 2 ? b[1] : 0.03;
        segs.push({
          ax: ax, az: az, ay: ay, bx: bx, bz: bz, by: by, hw: hw, bridge: !!isBridge,
          minx: Math.min(ax, bx) - hw, maxx: Math.max(ax, bx) + hw,
          minz: Math.min(az, bz) - hw, maxz: Math.max(az, bz) + hw
        });
      }
    }
    (map.roads || []).forEach(function (r) { addSegs(r.pts, (r.w || 6) * 0.5, !!r.bridge); });
    if (map.bridge && map.bridge.pts) addSegs(map.bridge.pts, (map.bridge.w || 11) * 0.5, true);
    (map.piers || []).forEach(function (p) { addSegs(p.pts, 1.2, false); });
    const segHash = buildHash(segs, 24, function (s) { return s; });
    G.summerWorld.roadSegs = segs;
    G.summerWorld.roadHash = segHash;

    G.sampleMapHeight = function (x, z) {
      let best = null, bestD = 1e9;
      const ids = queryHash(segHash, x, z, 14);
      for (let n = 0; n < ids.length; n++) {
        const s = segs[ids[n]];
        const dx = s.bx - s.ax, dz = s.bz - s.az;
        const L2 = dx * dx + dz * dz || 1e-9;
        const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
        const qx = s.ax + dx * t, qz = s.az + dz * t;
        const d = Math.hypot(x - qx, z - qz);
        if (d <= s.hw + 0.4 && d < bestD) {
          bestD = d;
          best = s.ay + (s.by - s.ay) * t;
          if (s.bridge) best += 0.02;
        }
      }
      return best;
    };
