    if (G.dressCoastalYards) G.dressCoastalYards(map, chunkOf, group);
    if (G.dressCoastalShore) G.dressCoastalShore(map, chunkOf, group, gridAt);
    if (G.plantCoastalGreenery) G.plantCoastalGreenery(map, chunkOf, group, gridAt);

